// Contract tests for the cart API. These fail until you implement the cart endpoints.
// Do NOT edit this file. Make the implementation pass it.
import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { startTestServer } from './helpers.js';

// Seeded products (see src/db.js)
const MUG = 1;        // 14.50, stock 12
const PLANT = 3;      // 18.00, stock 2
const NOTEBOOK = 4;   //  9.50, stock 30
const HEADPHONES = 5; // 89.99, stock 0

let api;
beforeEach(async () => { api = await startTestServer(); });
afterEach(() => api.close());

test('GET /api/cart starts empty', async () => {
  const { status, body } = await api.request('GET', '/api/cart');
  assert.equal(status, 200);
  assert.deepEqual(body, { items: [], totalCents: 0 });
});

test('POST /api/cart/items adds a product and returns the whole cart', async () => {
  const { status, body } = await api.request('POST', '/api/cart/items', { productId: MUG, quantity: 2 });
  assert.equal(status, 201);
  assert.deepEqual(body, {
    items: [{ productId: MUG, name: 'Ceramic Mug', emoji: '☕', priceCents: 1450, quantity: 2, lineTotalCents: 2900 }],
    totalCents: 2900,
  });
});

test('quantity defaults to 1', async () => {
  const { body } = await api.request('POST', '/api/cart/items', { productId: NOTEBOOK });
  assert.equal(body.items[0].quantity, 1);
});

test('adding the same product twice increments the quantity instead of duplicating it', async () => {
  await api.request('POST', '/api/cart/items', { productId: MUG, quantity: 1 });
  await api.request('POST', '/api/cart/items', { productId: NOTEBOOK, quantity: 1 });
  const { body } = await api.request('POST', '/api/cart/items', { productId: MUG, quantity: 3 });

  assert.equal(body.items.length, 2);
  assert.equal(body.items.find((i) => i.productId === MUG).quantity, 4);
  assert.equal(body.totalCents, 4 * 1450 + 950);
});

test('items keep the order in which they were first added', async () => {
  await api.request('POST', '/api/cart/items', { productId: NOTEBOOK });
  await api.request('POST', '/api/cart/items', { productId: MUG });
  await api.request('POST', '/api/cart/items', { productId: NOTEBOOK });
  const { body } = await api.request('GET', '/api/cart');
  assert.deepEqual(body.items.map((i) => i.productId), [NOTEBOOK, MUG]);
});

test('the cart is persisted: GET returns what was added', async () => {
  await api.request('POST', '/api/cart/items', { productId: PLANT, quantity: 1 });
  const { body } = await api.request('GET', '/api/cart');
  assert.equal(body.items.length, 1);
  assert.equal(body.items[0].productId, PLANT);
});

test('prices come from the database, never from the client', async () => {
  const { body } = await api.request('POST', '/api/cart/items', { productId: MUG, quantity: 1, priceCents: 1 });
  assert.equal(body.items[0].priceCents, 1450);
  assert.equal(body.totalCents, 1450);
});

test('400 when the body is invalid', async () => {
  for (const payload of [
    {},
    { productId: 'abc' },
    { productId: MUG, quantity: 0 },
    { productId: MUG, quantity: -1 },
    { productId: MUG, quantity: 1.5 },
    { productId: MUG, quantity: '2' },
  ]) {
    const { status, body } = await api.request('POST', '/api/cart/items', payload);
    assert.equal(status, 400, `expected 400 for ${JSON.stringify(payload)}`);
    assert.equal(typeof body.error, 'string');
  }
});

test('404 when the product does not exist', async () => {
  const { status, body } = await api.request('POST', '/api/cart/items', { productId: 999 });
  assert.equal(status, 404);
  assert.equal(typeof body.error, 'string');
});

test('409 when the requested quantity exceeds the stock', async () => {
  const outOfStock = await api.request('POST', '/api/cart/items', { productId: HEADPHONES });
  assert.equal(outOfStock.status, 409);
  assert.equal(typeof outOfStock.body.error, 'string');

  // Stock is checked against the TOTAL quantity in the cart, not just this request.
  assert.equal((await api.request('POST', '/api/cart/items', { productId: PLANT, quantity: 2 })).status, 201);
  const tooMany = await api.request('POST', '/api/cart/items', { productId: PLANT, quantity: 1 });
  assert.equal(tooMany.status, 409);

  // A rejected request must not change the cart.
  const { body } = await api.request('GET', '/api/cart');
  assert.equal(body.items.find((i) => i.productId === PLANT).quantity, 2);
});

test('DELETE /api/cart/items/:productId removes the product and returns the cart', async () => {
  await api.request('POST', '/api/cart/items', { productId: MUG, quantity: 2 });
  await api.request('POST', '/api/cart/items', { productId: NOTEBOOK });

  const { status, body } = await api.request('DELETE', `/api/cart/items/${MUG}`);
  assert.equal(status, 200);
  assert.deepEqual(body.items.map((i) => i.productId), [NOTEBOOK]);
  assert.equal(body.totalCents, 950);
});

test('DELETE returns 404 when the product is not in the cart', async () => {
  const { status } = await api.request('DELETE', `/api/cart/items/${MUG}`);
  assert.equal(status, 404);
});
